import json
import requests
from requests.adapters import HTTPAdapter

def call_api(url, 
             data=None, 
             headers=None,
             timeout=10, 
             auth=None, 
             post=True,
             max_retries=1,
             logger=None):
    headers = headers or {
        "Content-Type": "application/json",
        "service-code": "SL_POLYMAS",
    }
    if headers is None:
        headers = {'Content-Type': 'application/json',
                   'service-code': 'SI_POLYMAS'}
    if 'json' in headers.get('Content-Type') and post:
        post_data = json.dumps(data)
    else:
        post_data = data
    s = requests.Session()
    s.mount('http://', HTTPAdapter(max_retries=max_retries))
    try:
        if auth:
            if post:
                response = s.post(url, data=post_data, headers=headers, timeout=timeout, auth=auth)
            else:
                response = s.get(url, params=post_data, headers=headers, timeout=timeout, auth=auth)
        else:
            if post:
                response = s.post(url, data=post_data, headers=headers, timeout=timeout)
            else:
                response = requests.get(url, params=post_data, headers=headers, timeout=timeout)
        return response.json()
    except Exception as e:
        if logger:
            logger.exception()
        return {}
    # 计算文本相似度的函数
    @lru_cache(maxsize=1024)
    def _text_similarity(self, text):
        if not text:
            return 0
        max_sim = 0
        for q in self.q_list:
            max_len = max(len(q), len(text))
            if max_len == 0:
                continue
            sim1 = 1 - levenshtein_distance(q, text) / max_len
            sim2 = fuzz.QRatio(q, text) / 100
            sim = self._FUNC_SCORE(sim1, sim2)
            max_sim = max(max_sim, sim)
        return round(max_sim, 5)

    @lru_cache(maxsize=1024)
    def _FUNC_SCORE(self, sim1, sim2):
        return round(max(sim1, sim2) * (1 - 0.01) + min(sim1, sim2) * 0.01, 5)
